    // Create a minimal server for testing
    server = new WebSocket.Server({ port: 0 });
    const port = (server.address() as any).port;

    runtime = new GameRuntimeServer(port);
    runtime.metrics = new (require("../metrics")).MetricsTracker(); // Mock metrics

    // Override emitMessage to capture messages
    const originalEmit = runtime.emitMessage.bind(runtime);
    runtime.emitMessage = (msg: any) => {
      testState.systemMessages.push(msg);
      if (msg.type === "agent.action" || msg.type === "agent.feed") {
        testState.agentActions.push(`${msg.type}: ${JSON.stringify(msg.payload)}`);
      } else if (msg.type === "world.snapshot") {
        testState.worldSnapshots.push(msg.payload);
      }
    };

    // Connect a client
    const client = new WebSocket(`ws://localhost:${port}`);
    mockWs = client;

    // Wait for connection
    return new Promise<void>((resolve, reject) => {
      client.on("open", () => resolve());
      client.on("error", (err) => reject(err));
    });
  });

  afterEach(() => {
    return new Promise<void>((resolve) => {
      client.close();
      server.close();
      resolve();
    });
  });

  it("recovers from transient disconnect and does not duplicate side effects", async () => {
    // Start a session
    const startPayload = {
      version: PROTOCOL_VERSION,
      type: "session.start",
      payload: {
        seed: 12345,
        agents: [{ id: "agent-1", name: "TestAgent" }]
      }
    };

    await sendMessage(startPayload);
    await waitForPhase("running");

    // Send a build request to establish state
    const buildPayload = {
      version: PROTOCOL_VERSION,
      type: "build.request",
      payload: { goal: "build a stone wall" }
    };
    await sendMessage(buildPayload);
    await waitForBuildComplete();

    // Record initial world state
    const initialWorldState = JSON.stringify(testState.worldSnapshots[testState.worldSnapshots.length - 1]);

    // Simulate disconnection during gameplay
    const turnPayload = {
      version: PROTOCOL_VERSION,
      type: "agent.feed",
      payload: { role: "agent", agentId: "agent-1", text: "test action" }
    };
    await sendMessage(turnPayload);
    await waitForAgentActionQueueEmpty();

    // Disconnect the client
    mockWs.terminate();
    await new Promise(resolve => setTimeout(resolve, 100)); // Allow disconnect to register

    // Reconnect by sending a new client
    const newClient = new WebSocket(`ws://localhost:${(server.address() as any).port}`);
    await new Promise(resolve => newClient.on("open", resolve));

    // Send a system message to verify reconnect
    const systemMessage = {
      version: PROTOCOL_VERSION,
      type: "agent.feed",
      payload: { role: "system", text: "Reconnected" }
    };
    await sendMessage(systemMessage);
    await waitForSystemMessage("Reconnected");

    // Send another agent action
    const actionPayload = {
      version: PROTOCOL_VERSION,
      type: "agent.feed",
      payload: { role: "agent", agentId: "agent-1", text: "test action 2" }
    };
    await sendMessage(actionPayload);
    await waitForAgentActionQueueEmpty();

    // Verify no duplicate world changes
    const finalWorldState = JSON.stringify(testState.worldSnapshots[testState.worldSnapshots.length - 1]);
    expect(finalWorldState).toBe(initialWorldState);

    // Verify reconnect count
    const reconnectMessages = testState.systemMessages.filter(msg => 
      msg.type === "agent.feed" && 
      msg.payload.role === "system" && 
      msg.payload.text.includes("reconnect")
    );
    expect(reconnectMessages.length).toBe(1);

    // Verify no duplicate system messages
    const systemMessageCount = testState.systemMessages.filter(msg => 
      msg.type === "agent.feed" && 
      msg.payload.role === "system"
    ).length;
    expect(systemMessageCount).toBe(2); // Initial + reconnect
  });

